insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$valinhos$q$, $q$https://www.valinhos.sp.gov.br/portal/leis_decretos/13739/ (Dec. 12.123/2024) ; https://www.valinhos.sp.gov.br/portal/leis_decretos/14382/ (Dec. 12.264/2024) ; https://data.queridodiario.ok.org.br/3556206/2024-06-05/2499813bf2c79dc8bca34c284dc2a6de0303017e.pdf (DO ed. 2.658)$q$, $q$Atos oficiais de Valinhos: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM); limite municipal: IBGE (dados públicos, citar a fonte).$q$, 100, $q$Dec. 12.123/2024 (redação do Dec. 12.264/2024). ARTC (Anexo I) e Anexo IV como vias pelo nome do OSM; cinco logradouros do Anexo I não existem com esse nome no OSM (pendência). Regras de toda a malha municipal (VCPB fora das VTCP, VCPT) ficam desativadas, com o limite do município só como registro. Pendência para a SMU: o art. 9º, II, só libera o VCP sem AETC nas rotas de carga pesada, o que contradiz o Anexo IV (restrição só nos picos).$q$);
